PAGE=r'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panther Peptides | Jarvis Business OS</title><style>:root{--bg:#050a11;--p:#0c1725;--line:#28445f;--t:#f4f8fc;--m:#91a8bd;--g:#35d39a;--r:#ff7185;--a:#f0b64b;--b:#4b9dff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% -10%,#183a61,#07111f 38%,#04080e);color:var(--t);font:14px system-ui;min-height:100vh}.w{max-width:1600px;margin:auto;padding:16px}.top,.row,.actions,.sectionhead{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.top,.sectionhead{justify-content:space-between}.logo{width:48px;height:48px;border-radius:14px;background:linear-gradient(135deg,#4b9dff,#55dfc2);display:grid;place-items:center;color:#05101d;font-weight:950}h1,h2,h3,p{margin-top:0}.muted{color:var(--m)}.card{background:linear-gradient(180deg,#102138,#091522);border:1px solid var(--line);border-radius:17px;padding:16px}.btn,.field,select{border:1px solid #315779;background:#0a1726;color:white;padding:10px 12px;border-radius:10px;font:inherit}.btn{font-weight:750;cursor:pointer}.primary{background:#174d8b}.yes{background:#123d32}.no{background:#431b25}.field{width:100%}.hidden{display:none!important}.pill{display:inline-block;border:1px solid #365a7c;border-radius:999px;padding:4px 8px;font-size:11px}.connected,.online,.paid,.completed,.available,.income{color:#bdf5df;border-color:#286b59}.blocked,.not_connected,.expense{color:#ffabb8;border-color:#8c3448}.open,.queued,.awaiting_approval{color:#ffdc91;border-color:#8a6723}.tabs{display:flex;gap:7px;margin:13px 0;overflow:auto}.tab.active{outline:2px solid var(--b)}.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin:12px 0}.kpi b{display:block;font-size:25px;margin-top:5px}.grid2{display:grid;grid-template-columns:1.3fr .7fr;gap:12px}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.event{border:1px solid #203b57;border-radius:11px;padding:10px;margin-top:8px;background:#081522}.bigask{border:2px solid #4b9dff;background:linear-gradient(135deg,#102a49,#102038);padding:20px}.bigask h2{font-size:22px}.askbox{display:grid;grid-template-columns:1fr auto;gap:8px}.notice{margin:12px 0;padding:10px 13px;border-radius:11px;border:1px solid #8a6723;background:#2a2110;color:#ffdc91}.table{overflow:auto}table{width:100%;border-collapse:collapse;min-width:760px}th,td{padding:9px;border-bottom:1px solid #1d354e;text-align:left}.chart{height:180px;display:flex;align-items:flex-end;gap:4px;border-bottom:1px solid #294765;padding-top:20px}.bar{flex:1;min-width:5px;background:linear-gradient(#55dfc2,#4b9dff);border-radius:5px 5px 0 0;position:relative}.bar:hover:after{content:attr(data-tip);position:absolute;bottom:100%;left:0;background:#02060b;padding:5px;border-radius:6px;white-space:nowrap;z-index:3}.forms{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.login{max-width:480px;margin:8vh auto}.approval{border:2px solid var(--a);margin:12px 0}.jarvisbox{border-left:4px solid var(--b)}@media(max-width:1000px){.kpis{grid-template-columns:repeat(2,1fr)}.grid2,.grid3,.forms,.askbox{grid-template-columns:1fr}.w{padding:9px}}</style></head><body><div class="w"><header class="top"><div class="row"><div class="logo">PP</div><div><h1>Panther Peptides</h1><div class="muted">Jarvis Business OS · <b>BUSINESS-OS-241</b> · <span id="ver"></span></div></div></div><div class="actions"><span id="state" class="pill open">Starting</span><button class="btn" onclick="load()">Refresh</button><button id="logout" class="btn hidden" onclick="doLogout()">Logout</button></div></header><div id="notice" class="notice hidden"></div><div id="login" class="card login"><h2>Owner Access</h2><input id="pw" class="field" type="password" placeholder="Owner password" onkeydown="if(event.key==='Enter')doLogin()"><p></p><button class="btn primary" onclick="doLogin()">Open Business OS</button><p id="err"></p></div><main id="app" class="hidden"><section id="approval" class="card approval hidden"></section><section id="jarvisAsk" class="card bigask"></section><div class="tabs"><button class="btn tab active" onclick="tab('executive',this)">Executive</button><button class="btn tab" onclick="tab('sales',this)">Sales & Orders</button><button class="btn tab" onclick="tab('finance',this)">Cash & Finance</button><button class="btn tab" onclick="tab('inventory',this)">Inventory</button><button class="btn tab" onclick="tab('purchasing',this)">Purchasing</button><button class="btn tab" onclick="tab('marketing',this)">Marketing</button><button class="btn tab" onclick="tab('jarvis',this)">Jarvis Operations</button><button class="btn tab" onclick="tab('knowledge',this)">Knowledge</button><button class="btn tab" onclick="tab('systems',this)">Integrations</button></div><section id="executive"><h2>Business at a Glance</h2><div id="kpis" class="kpis"></div><div class="grid2"><div class="card"><div class="sectionhead"><h2>30-Day Sales</h2><span class="muted">Real entered/connected orders only</span></div><div id="saleschart" class="chart"></div></div><div class="card jarvisbox"><h2>Jarvis Management Brief</h2><div id="brief"></div></div></div><div class="grid3" style="margin-top:12px"><div class="card"><h3>Cash Position</h3><div id="cashbrief"></div></div><div class="card"><h3>Inventory Position</h3><div id="invbrief"></div></div><div class="card"><h3>Launch Readiness</h3><div id="launchbrief"></div></div></div></section><section id="sales" class="card hidden"><h2>Sales & Orders</h2><p class="muted">Manual now; connected commerce will feed the same ledger later.</p><div class="forms"><input id="onum" class="field" placeholder="Order #"><input id="ocust" class="field" placeholder="Customer"><input id="ototal" class="field" type="number" step=".01" placeholder="Total"><input id="ocogs" class="field" type="number" step=".01" placeholder="COGS"><button class="btn primary" onclick="addOrder()">Add Order</button></div><div class="table"><table><thead><tr><th>Date</th><th>Order</th><th>Customer</th><th>Status</th><th>Total</th><th>COGS</th></tr></thead><tbody id="orderrows"></tbody></table></div></section><section id="finance" class="card hidden"><h2>Cash & Finance</h2><div class="forms"><select id="ctype"><option value="income">Cash In</option><option value="expense">Cash Out</option></select><input id="ccat" class="field" placeholder="Category"><input id="cdesc" class="field" placeholder="Description"><input id="camt" class="field" type="number" step=".01" placeholder="Amount"><button class="btn primary" onclick="addCash()">Add Transaction</button></div><div class="table"><table><thead><tr><th>Date</th><th>Type</th><th>Category</th><th>Description</th><th>Amount</th></tr></thead><tbody id="cashrows"></tbody></table></div></section><section id="inventory" class="card hidden"><h2>Inventory</h2><div class="forms"><input id="ip" class="field" placeholder="Product"><input id="il" class="field" placeholder="Lot"><input id="iq" class="field" type="number" placeholder="Qty"><input id="icost" class="field" type="number" step=".01" placeholder="Unit cost"><input id="iprice" class="field" type="number" step=".01" placeholder="Selling price"><select id="is"><option>available</option><option>held</option><option>quarantine</option><option>sold</option></select><button class="btn primary" onclick="addInv()">Add / Update</button></div><div class="table"><table><thead><tr><th>Product</th><th>Lot</th><th>Qty</th><th>Cost</th><th>Price</th><th>Status</th><th>COA</th></tr></thead><tbody id="invrows"></tbody></table></div></section><section id="purchasing" class="card hidden"><h2>Purchasing</h2><div class="forms"><input id="posup" class="field" placeholder="Supplier"><input id="ponum" class="field" placeholder="PO #"><input id="poamt" class="field" type="number" step=".01" placeholder="Amount"><input id="poexp" class="field" type="date"><button class="btn primary" onclick="addPO()">Add PO</button></div><div id="polist"></div></section><section id="marketing" class="card hidden"><h2>Marketing Performance</h2><div class="forms"><input id="mchan" class="field" placeholder="Channel"><input id="mspend" class="field" type="number" step=".01" placeholder="Spend"><input id="mrev" class="field" type="number" step=".01" placeholder="Attributed revenue"><input id="morders" class="field" type="number" placeholder="Orders"><button class="btn primary" onclick="addMarketing()">Add Performance</button></div><div id="mlist"></div></section><section id="jarvis" class="hidden"><div class="grid2"><div class="card"><div class="sectionhead"><h2>Objectives & Work</h2><button class="btn primary" onclick="newObjective()">Give Objective</button></div><div id="objectives"></div></div><div class="card"><h2>Activity</h2><div id="activity"></div></div></div><div class="card" style="margin-top:12px"><h2>Improve Jarvis / Dashboard</h2><p class="muted">Describe what you want changed. Jarvis records it as an engineering objective and will identify any missing engineering connection.</p><div class="askbox"><input id="upgrade" class="field" placeholder="Example: Add wholesale pipeline and margin reporting"><button class="btn primary" onclick="upgrade()">Request Upgrade</button></div><div id="upgrades"></div></div></section><section id="knowledge" class="card hidden"><h2>Knowledge & Business Memory</h2><form onsubmit="uploadKnowledge(event)"><div class="forms"><input id="kf" class="field" type="file" required><input id="kc" class="field" placeholder="Category"><input id="kt" class="field" placeholder="Tags"><button class="btn primary">Upload</button></div></form><div id="knowlist"></div></section><section id="systems" class="card hidden"><h2>Integrations</h2><div id="integrations"></div></section></main></div><script>const $=x=>document.getElementById(x),money=n=>'$'+Number(n||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}),esc=s=>String(s??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));let D,A,Q;async function req(u,o={}){let r=await fetch(u,{...o,cache:'no-store'}),d=await r.json().catch(()=>({}));if(!r.ok){let x=Error(d.detail||d.error||'HTTP '+r.status);x.status=r.status;throw x}return d}function note(s){$('notice').textContent=s;$('notice').classList.toggle('hidden',!s)}function pill(s){return `<span class="pill ${esc(s)}">${esc(s)}</span>`}async function doLogin(){try{await req('/api/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:$('pw').value})});$('pw').value='';load()}catch(e){$('err').textContent=e.message}}async function doLogout(){await fetch('/api/logout',{method:'POST'});location.reload()}function tab(id,b){['executive','sales','finance','inventory','purchasing','marketing','jarvis','knowledge','systems'].forEach(x=>$(x).classList.toggle('hidden',x!==id));document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active')}async function load(){try{D=await req('/api/dashboard');$('login').classList.add('hidden');$('app').classList.remove('hidden');$('logout').classList.remove('hidden');$('ver').textContent='v'+D.version;$('state').textContent=D.operator.worker_alive?'Jarvis online':'Runtime attention';$('state').className='pill '+(D.operator.worker_alive?'online':'blocked');render()}catch(e){if(e.status===401){$('login').classList.remove('hidden');$('app').classList.add('hidden')}else note(e.message)}}function render(){let x=D.executive,iv=x.inventory||{};$('kpis').innerHTML=[['Sales Today',money(x.sales_today)],['Sales MTD',money(x.sales_mtd)],['Cash Available',money(x.cash_balance)],['Gross Profit MTD',money(x.gross_profit_mtd)],['Inventory Value',money(iv.inventory_cost_value)],['Open PO Commitment',money(x.open_po_commitment)],['Orders MTD',x.orders_mtd],['Avg Order',money(x.average_order_value)],['Gross Margin',Number(x.gross_margin_pct).toFixed(1)+'%'],['Marketing Spend',money(x.marketing_spend_mtd)],['ROAS',Number(x.roas).toFixed(2)+'x'],['Questions for Owner',x.unanswered_questions]].map(a=>`<div class="card kpi"><span class="muted">${a[0]}</span><b>${a[1]}</b></div>`).join('');let tr=x.sales_trend||[],mx=Math.max(1,...tr.map(z=>z.sales));$('saleschart').innerHTML=tr.length?tr.map(z=>`<div class="bar" style="height:${Math.max(3,z.sales/mx*100)}%" data-tip="${esc(z.date)} ${money(z.sales)}"></div>`).join(''):'<div class="muted">Sales will chart here as orders are entered or connected.</div>';$('cashbrief').innerHTML=`<div class="event"><b>${money(x.cash_balance)}</b> calculated cash<br><span class="muted">Cash in ${money(x.cash_in_total)} · cash out ${money(x.cash_out_total)}</span></div><div class="event">Open purchase commitments: <b>${money(x.open_po_commitment)}</b></div>`;$('invbrief').innerHTML=`<div class="event"><b>${iv.available_units||0}</b> available units · ${iv.skus||0} lots/SKUs</div><div class="event">Cost value <b>${money(iv.inventory_cost_value)}</b><br>Potential retail value <b>${money(iv.inventory_retail_value)}</b></div>`;let connected=(D.integrations||[]).filter(i=>i.status==='connected').length;$('launchbrief').innerHTML=`<div class="event"><b>${connected}/${(D.integrations||[]).length}</b> systems connected</div><div class="event"><b>${x.unanswered_questions}</b> management questions still need your input</div>`;Q=(D.questions||[])[0];$('jarvisAsk').innerHTML=Q?`<div class="muted">JARVIS NEEDS YOUR INPUT · ${esc(Q.category).toUpperCase()}</div><h2>${esc(Q.question)}</h2><p class="muted">Why I'm asking: ${esc(Q.why||'Needed to operate the business.')}</p><div class="askbox"><input id="answer" class="field" placeholder="Answer Jarvis here" onkeydown="if(event.key==='Enter')answerJarvis()"><button class="btn primary" onclick="answerJarvis()">Answer & Continue</button></div>`:`<div class="muted">JARVIS MANAGEMENT LOOP</div><h2>No owner questions are waiting.</h2><p class="muted">Jarvis will surface decisions and missing business information here as the company develops.</p>`;$('brief').innerHTML=`<div class="event">${x.unanswered_questions?`I have <b>${x.unanswered_questions}</b> unanswered business questions. Answer them and I will keep moving through company setup.`:'I have the owner-input queue cleared.'}</div><div class="event">${D.operator.blocked?`<b>${D.operator.blocked}</b> objectives are blocked and need review.`:'No currently blocked objectives.'}</div><div class="event">Executive figures come only from real ledger entries and connected systems.</div>`;$('orderrows').innerHTML=(D.orders||[]).map(o=>`<tr><td>${esc(o.order_date)}</td><td>${esc(o.order_number||'—')}</td><td>${esc(o.customer_name||'—')}</td><td>${pill(o.status)}</td><td>${money(o.total)}</td><td>${money(o.cogs)}</td></tr>`).join('')||'<tr><td colspan=6 class="muted">No orders yet.</td></tr>';$('cashrows').innerHTML=(D.cash||[]).map(c=>`<tr><td>${esc(c.txn_date)}</td><td>${pill(c.type)}</td><td>${esc(c.category)}</td><td>${esc(c.description)}</td><td>${money(c.amount)}</td></tr>`).join('')||'<tr><td colspan=5 class="muted">No cash transactions yet.</td></tr>';$('invrows').innerHTML=(D.inventory||[]).map(i=>`<tr><td><b>${esc(i.product)}</b></td><td>${esc(i.lot||'—')}</td><td>${i.quantity}</td><td>${money(i.unit_cost)}</td><td>${money(i.unit_price)}</td><td>${pill(i.status)}</td><td>${esc(i.coa_status)}</td></tr>`).join('')||'<tr><td colspan=7 class="muted">No inventory yet.</td></tr>';$('polist').innerHTML=(D.purchases||[]).map(p=>`<div class="event"><b>${esc(p.supplier)}</b> · ${esc(p.po_number||'PO')} ${pill(p.status)}<br>${money(p.amount)} · expected ${esc(p.expected_date||'not set')}</div>`).join('')||'<p class="muted">No purchase orders.</p>';$('mlist').innerHTML=(D.marketing||[]).map(m=>`<div class="event"><b>${esc(m.channel)}</b> · spend ${money(m.spend)} · revenue ${money(m.revenue)} · ROAS ${m.spend?(m.revenue/m.spend).toFixed(2):'0.00'}x</div>`).join('')||'<p class="muted">No marketing data.</p>';$('objectives').innerHTML=(D.objectives||[]).map(o=>`<div class="event"><b>#${o.id} ${esc(o.title)}</b> ${pill(o.state)}<br><span class="muted">${esc(o.result||o.blocked_reason||'Jarvis work item')}</span></div>`).join('')||'<p class="muted">No objectives.</p>';$('activity').innerHTML=(D.activity||[]).slice(0,20).map(a=>`<div class="event"><b>${esc(a.tool||a.kind)}</b> ${pill(a.status)}<br><span class="muted">Objective #${a.objective_id}</span></div>`).join('')||'<p class="muted">No activity.</p>';$('upgrades').innerHTML=(D.upgrades||[]).map(u=>`<div class="event"><b>${esc(u.title)}</b> ${pill(u.status)}<br><span class="muted">${esc(u.request)}</span></div>`).join('');$('knowlist').innerHTML=(D.knowledge||[]).map(k=>`<div class="event"><b>${esc(k.name)}</b><br><span class="muted">${esc(k.category||'general')} · ${esc(k.tags||'')}</span></div>`).join('')||'<p class="muted">No knowledge files.</p>';$('integrations').innerHTML=(D.integrations||[]).map(i=>`<div class="event sectionhead"><div><b>${esc(i.name)}</b><div class="muted">${esc(i.detail)}</div></div>${pill(i.status)}</div>`).join('');A=D.approval;$('approval').classList.toggle('hidden',!A);if(A)$('approval').innerHTML=`<div class="muted">OWNER APPROVAL REQUIRED</div><h2>${esc(A.question)}</h2><button class="btn yes" onclick="approve(true)">Approve</button> <button class="btn no" onclick="approve(false)">Deny</button>`}async function answerJarvis(){if(!Q)return;let a=$('answer').value.trim();if(!a)return;await req('/api/questions/'+Q.id+'/answer',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({answer:a})});note('Jarvis saved your answer and moved to the next business question.');load()}async function approve(ok){await req('/api/approvals/'+A.id,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({approved:ok})});load()}async function addOrder(){await req('/api/orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({order_number:$('onum').value,customer_name:$('ocust').value,total:Number($('ototal').value||0),subtotal:Number($('ototal').value||0),cogs:Number($('ocogs').value||0)})});load()}async function addCash(){await req('/api/cash',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({type:$('ctype').value,category:$('ccat').value||'general',description:$('cdesc').value,amount:Number($('camt').value||0)})});load()}async function addInv(){if(!$('ip').value.trim())return;await req('/api/inventory',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({product:$('ip').value,lot:$('il').value,quantity:Number($('iq').value||0),unit_cost:Number($('icost').value||0),unit_price:Number($('iprice').value||0),status:$('is').value})});load()}async function addPO(){if(!$('posup').value.trim())return;await req('/api/purchases',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({supplier:$('posup').value,po_number:$('ponum').value,amount:Number($('poamt').value||0),expected_date:$('poexp').value})});load()}async function addMarketing(){if(!$('mchan').value.trim())return;await req('/api/marketing',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({channel:$('mchan').value,spend:Number($('mspend').value||0),revenue:Number($('mrev').value||0),orders:Number($('morders').value||0)})});load()}async function newObjective(){let x=prompt('What business outcome should Jarvis accomplish?');if(!x)return;await req('/api/objectives',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({objective:x,priority:50})});load()}async function upgrade(){let x=$('upgrade').value.trim();if(!x)return;await req('/api/dashboard-upgrades',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title:x.slice(0,100),request:x})});$('upgrade').value='';note('Dashboard improvement added to Jarvis engineering work.');load()}async function uploadKnowledge(ev){ev.preventDefault();let f=new FormData();f.append('file',$('kf').files[0]);f.append('category',$('kc').value||'general');f.append('tags',$('kt').value||'');await req('/api/knowledge',{method:'POST',body:f});ev.target.reset();load()}load();setInterval(()=>{if(!$('app').classList.contains('hidden'))load()},5000)</script></body></html>'''
